async function cdqOpenPdf(id){
  afficherMessage('Préparation du PDF…',true);
  try{
    const rec=await window.cdqLoadPdfRecord(id);
    if(window.cdqPdfReaderPreference()==='cdq'){
      await window.cdqOpenPdfInternal(id,rec);
    }else{
      window.cdqShowPdfReaderChoice(id,rec);
    }
    return true;
  }
  catch(e){
    afficherErreur(e);
    throw e;
  }
}
window.cdqOpenPdf=cdqOpenPdf;

